CREATE TABLE request_proposals(id uuid NOT NULL,version integer NOT NULL,project_id uuid NOT NULL,run_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES members,selection_id uuid NOT NULL REFERENCES sourcing_selections,need_id uuid NOT NULL REFERENCES procurement_needs,need_version integer NOT NULL,candidate_id uuid NOT NULL,candidate_version integer NOT NULL,selected_specification text NOT NULL,calculation jsonb NOT NULL,recipient_id text NOT NULL,address text NOT NULL,desired_date date NOT NULL,exact_text text NOT NULL,content_hash text NOT NULL,status text NOT NULL CHECK(status IN ('draft','pending','approved','rejected','invalidated','expired')),expires_at timestamptz NOT NULL,checkpoint_id uuid NOT NULL UNIQUE REFERENCES live_interactions DEFERRABLE INITIALLY DEFERRED,token_hash text NOT NULL,configuration_hash text NOT NULL,alternative_reviewed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id,version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE approvals(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,proposal_id uuid NOT NULL,proposal_version integer NOT NULL,actor_id uuid NOT NULL REFERENCES members,decision text NOT NULL CHECK(decision IN ('approve','reject')),decided_at timestamptz NOT NULL,content_hash text NOT NULL,recipient_id text NOT NULL,UNIQUE(proposal_id,proposal_version),FOREIGN KEY(proposal_id,proposal_version) REFERENCES request_proposals(id,version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE outbound_requests(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,proposal_id uuid NOT NULL,proposal_version integer NOT NULL,approval_id uuid NOT NULL UNIQUE REFERENCES approvals,payload text NOT NULL,recipient_id text NOT NULL,status text NOT NULL CHECK(status IN ('pending','sending','sent','uncertain','failed','cancelled')),provider_message_id text,attempted_at timestamptz,uncertain_at timestamptz,UNIQUE(proposal_id,proposal_version),FOREIGN KEY(proposal_id,proposal_version) REFERENCES request_proposals(id,version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE proposal_amendments(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,proposal_id uuid NOT NULL,proposal_version integer NOT NULL,need_version integer NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'required',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(proposal_id,proposal_version,need_version),FOREIGN KEY(proposal_id,proposal_version) REFERENCES request_proposals(id,version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
